<?php
namespace App\Http\Requests\MeetingRequests;
use Illuminate\Foundation\Http\FormRequest;
class FinalizeMeetingRequest extends FormRequest { public function authorize(): bool { return $this->user()?->isActive() === true; } public function rules(): array { return ['meeting_date'=>['required','date'],'start_time'=>['required','date_format:H:i'],'end_time'=>['required','date_format:H:i'],'location'=>['required','string','max:255'],'chairperson_employee_id'=>['required','integer','exists:employees,id'],'agenda'=>['nullable','string','max:10000']]; } public function messages(): array { return ['required'=>'وارد کردن :attribute الزامی است.']; } public function attributes(): array { return ['meeting_date'=>'تاریخ جلسه','start_time'=>'زمان آغاز','end_time'=>'زمان ختم','location'=>'محل جلسه','chairperson_employee_id'=>'رئیس جلسه','agenda'=>'آجندا']; } }